window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e4c2cba66e28c354"]={"versions": [{"id": "FIG-e4c2cba66e28c354", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene der Metamodellierung für die AUTOSAR-ECU-Konfiguration, AUTOSAR TPS ECU Configuration). Das Diagramm veranschaulicht exemplarisch die Definition eines Multi-Configuration-Containers (<code>multipleConfigurationContainer = true</code>) am Beispiel des BSW-Moduls <code>Adc</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf Instanzen von Metamodellelementen und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Adc :EcucModuleDef</code>: Moduldefinition mit Attributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.\n</li><li><code>AdcConfigSet :EcucParamConfContainerDef</code>: Containerdefinition, über die Komposition <code>+container</code> an <code>Adc</code> angebunden; Attribut <code>multipleConfigurationContainer = true</code>.\n</li><li><code>AdcHwUnit :EcucParamConfContainerDef</code>: Sub-Container von <code>AdcConfigSet</code> (Rolle <code>+subContainer</code>), Attribute <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.\n</li><li><code>AdcHwUnitId :EcucEnumerationParamDef</code>: Parameterdefinition innerhalb von <code>AdcHwUnit</code> (Rolle <code>+parameter</code>).\n</li><li><code>AdcGroup :EcucParamConfContainerDef</code>: Sub-Container von <code>AdcHwUnit</code> (Rolle <code>+subContainer</code>), Attribute <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm auf Instanzebene zur Konfigurationsdefinition (BSW-Moduldef-Struktur). Es stellt keine Laufzeit- oder Sequenzabläufe dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Modellstruktur für post-build- bzw. mehrfach konfigurierbare Container in AUTOSAR ECU-Konfigurationsbeschreibungen:</p>\n<ul class=\"fig-list\"><li>Wenn ein Container als <code>multipleConfigurationContainer = true</code> deklariert ist (hier <code>AdcConfigSet</code>), kapselt er die modulspezifischen Konfigurationsvarianten bzw. Parametersätze.\n</li><li>Kind-Container wie <code>AdcHwUnit</code> und darin geschachtelte Container (<code>AdcGroup</code>) sowie Parameter (<code>AdcHwUnitId</code>) sind strukturell Bestandteil dieses konfigurierbaren Sets.\n</li><li>Bei der Konfigurationserstellung und Tooling-Validierung müssen die angegebenen Multiplizitäten (<code>0..1</code> für das Modul, <code>1..*</code> für Container) eingehalten werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7e0ca6e1208c1a7d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene der Metamodellierung für die AUTOSAR-ECU-Konfiguration, AUTOSAR TPS ECU Configuration). Das Diagramm veranschaulicht exemplarisch die Definition eines Multi-Configuration-Containers (<code>multipleConfigurationContainer = true</code>) am Beispiel des BSW-Moduls <code>Adc</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf Instanzen von Metamodellelementen und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Adc :EcucModuleDef</code>: Moduldefinition mit Attributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.\n</li><li><code>AdcConfigSet :EcucParamConfContainerDef</code>: Containerdefinition, über die Komposition <code>+container</code> an <code>Adc</code> angebunden; Attribut <code>multipleConfigurationContainer = true</code>.\n</li><li><code>AdcHwUnit :EcucParamConfContainerDef</code>: Sub-Container von <code>AdcConfigSet</code> (Rolle <code>+subContainer</code>), Attribute <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.\n</li><li><code>AdcHwUnitId :EcucEnumerationParamDef</code>: Parameterdefinition innerhalb von <code>AdcHwUnit</code> (Rolle <code>+parameter</code>).\n</li><li><code>AdcGroup :EcucParamConfContainerDef</code>: Sub-Container von <code>AdcHwUnit</code> (Rolle <code>+subContainer</code>), Attribute <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm auf Instanzebene zur Konfigurationsdefinition (BSW-Moduldef-Struktur). Es stellt keine Laufzeit- oder Sequenzabläufe dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Modellstruktur für post-build- bzw. mehrfach konfigurierbare Container in AUTOSAR ECU-Konfigurationsbeschreibungen:</p>\n<ul class=\"fig-list\"><li>Wenn ein Container als <code>multipleConfigurationContainer = true</code> deklariert ist (hier <code>AdcConfigSet</code>), kapselt er die modulspezifischen Konfigurationsvarianten bzw. Parametersätze.\n</li><li>Kind-Container wie <code>AdcHwUnit</code> und darin geschachtelte Container (<code>AdcGroup</code>) sowie Parameter (<code>AdcHwUnitId</code>) sind strukturell Bestandteil dieses konfigurierbaren Sets.\n</li><li>Bei der Konfigurationserstellung und Tooling-Validierung müssen die angegebenen Multiplizitäten (<code>0..1</code> für das Modul, <code>1..*</code> für Container) eingehalten werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e4c2cba66e28c354", "to": "FIG-7e0ca6e1208c1a7d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In allen fünf UML-Objektkästen (<code>Adc :EcucModuleDef</code>, <code>AdcConfigSet :EcucParamConfContainerDef</code>, <code>AdcHwUnit :EcucParamConfContainerDef</code>, <code>AdcHwUnitId :EcucEnumerationParamDef</code>, <code>AdcGroup :EcucParamConfContainerDef</code>) wurde eine horizontale Trennlinie zwischen dem Objektnamen (Kopfbereich) und dem Attributbereich eingefügt.\n</li></ul>"}]};
